import{_ as n,l as s,o,c as i,v as d,p as c,x as t,d as r,i as p,S as A,b as e}from"./chunks/framework.InCnrqk-.js";const V=JSON.parse('{"title":"YOCO","description":"","frontmatter":{"title":"YOCO","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/yoco.md","filePath":"llm/yoco.md","lastUpdated":1789023840000}'),E={name:"llm/yoco.md"};function h(u,a,O,m,C,B){const l=s("Mermaid");return o(),i("div",null,[a[1]||(a[1]=d('<h1 id="yoco" tabindex="-1">YOCO <a class="header-anchor" href="#yoco" aria-label="Permalink to &quot;YOCO&quot;">​</a></h1><div class="epigraph"><p>自注意力只在前半段产生一份全局 KV，后半段当解码器去读它；缓存只写一次。</p><footer>—— Sun et al., You Only Cache Once: Decoder-Decoder Architectures for Language Models, 2024</footer></div><p><a href="/llm/cross-layer-kv-sharing">上一课</a>把相邻层绑成 KV 组，组数仍随深度涨。YOCO 把共享推到极端：整网只物化<strong>一份</strong>可供全局读取的 KV，后面的层不再各自缓存。名字里的 decoder-decoder 指两段都是解码器栈，不是编解码器的交叉注意力课。后课多 token 注意力改的是一次读取看几个位置；本课改的是<strong>谁负责写缓存</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CLA 的 \\(g=2\\) 仍留下 \\(L/2\\) 份缓存。GQA 只收头。长上下文解码的内存墙是「层 × 头 × 长度」。缺口是一种计算图：让早期层（或专门的自注意力段）把过去写成一张全局记忆，晚期层只带轻量的局部或无 KV 的模块去读它，从而 <strong>You Only Cache Once</strong>。</p><p>若晚期层完全不再做自注意力，表达力会掉回「深层是前馈叠在固定记忆上」。YOCO 必须在「只缓存一次」和「深层仍能混合新 token」之间划槽位。</p><p><span class="marginnote">这不是 <a href="/llm/encoder-decoder-attention">编码器–解码器注意力</a> 的翻译架构。源与目标没有分开的双向编码器；前半段也是因果的，只是它的 KV 被后半段当记忆反复读。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Sun 等人的解码器–解码器：前半 \\(L/2\\) 层标准因果自注意力，产出并缓存全局 KV；后半 \\(L/2\\) 层用交叉注意力读这份 KV，自身的自注意力改成窗口或高效变体，不再存全局缓存。生成第 \\(t\\) 个 token 时，全局记忆仍是前半段对 \\(1..t\\) 的 KV，长度随 \\(t\\) 涨，但层维是 1 而不是 \\(L\\)。</p><p>训练与推理的掩码仍因果：前半段看不到未来；后半段读前半段记忆时，记忆本身已按因果写成。没有「用未来摘要编码文章」的泄漏。</p><h3 id="和-cla、gqa-的组合" tabindex="-1">和 CLA、GQA 的组合 <a class="header-anchor" href="#和-cla、gqa-的组合" aria-label="Permalink to &quot;和 CLA、GQA 的组合&quot;">​</a></h3><p>全局那一份 KV 仍可 GQA 少头。CLA 发生在前半段内部则再度减层维，但 YOCO 的主收益已经来自后半段不缓存。工程上优先 YOCO 的两段划分，再决定前半段要不要 CLA。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>深度被重新解释：浅层负责<strong>写</strong>可检索记忆，深层负责<strong>读</strong>并做局部精炼。这与人类读文档时「先做索引、再反复查」同构，也与编解码器「编码器写记忆」同构，只是记忆是因果前缀而不是双向源。后半段若完全没有自注意力，当前 token 与最近邻居的混合全靠读全局 KV，近距模式可能变差，所以常留窗口自注意力——窗口 KV 长度固定，不随上下文线性涨，或涨得很慢。</p><p>计算上预训练仍要跑前半段的全局注意力，YOCO 不是训练线性化；它是推理缓存策略与层功能分化。解码第 \\(t\\) 步时，全局 KV 长度仍是 \\(t\\)，只是层维为 1：省的是「层 × 长度」，不是把长度变成常数。与 <a href="/llm/cross-layer-kv-sharing">CLA</a> 的 \\(L/g\\) 份相比，YOCO 赌后半段根本不必拥有自己的全局表。</p><p><span class="marginnote">前半段若太浅，记忆质量不够，后半段再深也是在读差索引。切分点是超参，与后课混合 SSM/注意力的层比是同一类问题：谁写状态、谁读状态。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>检查点与推理引擎按「每层一份 KV」写的接口要改。投机解码、前缀缓存的块对齐以全局记忆为准。把已有均匀层模型切成 YOCO 需要再训或蒸馏，不能只在推理图里丢掉深层 KV（那是 eviction，深层从未学过当纯读者）。窗口太大，ONCE 名不副实；窗口太小，局部句法受损。</p>',18)),(o(),c(A,null,{default:t(()=>[p(l,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20Pref%5B%22%E5%89%8D%E5%8D%8A%E6%AE%B5%E5%9B%A0%E6%9E%9C%E8%87%AA%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%20--%3E%20GKV%5B%22%E5%85%A8%E5%B1%80%20KV%20%E5%8F%AA%E5%86%99%E4%B8%80%E6%AC%A1%22%5D%0A%20%20GKV%20--%3E%20Cross%5B%22%E5%90%8E%E5%8D%8A%E6%AE%B5%E4%BA%A4%E5%8F%89%E8%AF%BB%E5%8F%96%22%5D%0A%20%20Win%5B%22%E7%AA%97%E5%8F%A3%E8%87%AA%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%20--%3E%20Out%5B%22%E6%B7%B1%E5%B1%82%E8%BE%93%E5%87%BA%22%5D%0A%20%20Cross%20--%3E%20Out%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"YOCO 让前半段写一份全局 KV，后半段只读它并辅以窗口混合，缓存沿层只留一次。"),e("li",null,"两段都是因果解码器，不是双向编码器加解码器。"),e("li",null,"切分点决定记忆质量；窗口决定近距能力与是否真的只缓存一次。"),e("li",null,"不能把均匀层模型在推理时直接丢掉深层 KV 来冒充 YOCO。"),e("li",null,"出处：Sun et al., 2024。")],-1))])}const g=n(E,[["render",h]]);export{V as __pageData,g as default};
